const wb = Workbook.create();
wb.comments.setSelf({displayName:"Vikram Indla"});
const palette={navy:"#16324F",blue:"#2E5B88",teal:"#2F7F7A",light:"#EAF0F5",green:"#DDEFE2",amber:"#FFF1C7",red:"#F8D7DA",grey:"#E5E7EB",white:"#FFFFFF",ink:"#1F2937"};
function colLetter(n){let s="";while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s}
function addTableSheet(name, headers, rows, widths={}) {
  const s=wb.worksheets.add(name); s.showGridLines=false;
  s.getRangeByIndexes(0,0,1,headers.length).merge();
  s.getCell(0,0).values=[[name.replaceAll("_"," ")]];
  s.getCell(0,0).format={fill:palette.navy,font:{bold:true,color:palette.white,size:16},verticalAlignment:"center"};
  s.getRangeByIndexes(1,0,1,headers.length).values=[[`Audit snapshot · ${now} · commit ${shortCommit}`,...Array(headers.length-1).fill("")]];
  s.getRangeByIndexes(1,0,1,headers.length).format={fill:palette.light,font:{italic:true,color:palette.ink}};
  s.getRangeByIndexes(3,0,1,headers.length).values=[headers];
  if(rows.length) s.getRangeByIndexes(4,0,rows.length,headers.length).values=rows;
  const end=4+Math.max(rows.length,1); const endCol=colLetter(headers.length);
  s.getRange(`A4:${endCol}${end}`).format={wrapText:true,verticalAlignment:"top",font:{size:9},borders:{preset:"all",style:"thin",color:"#D1D5DB"}};
  s.getRange(`A4:${endCol}4`).format={fill:palette.blue,font:{bold:true,color:palette.white,size:9},wrapText:true};
  if(rows.length) { const t=s.tables.add(`A4:${endCol}${4+rows.length}`,true,`${name.replace(/[^A-Za-z0-9]/g,"").slice(0,20)}Tbl`); t.style="TableStyleMedium2"; }
  s.freezePanes.freezeRows(4);
  for(let i=0;i<headers.length;i++) s.getRangeByIndexes(0,i,end,1).format.columnWidth=widths[i]||Math.min(34,Math.max(12,headers[i].length+3));
  s.getRange(`A1:${endCol}${end}`).format.rowHeight=30;
  return s;
}

